import sys

print(sys.getrecursionlimit())        # 1000

def depth(n):
    return 0 if n == 0 else 1 + depth(n - 1)

try:
    depth(5000)
except RecursionError as e:
    print(type(e).__mro__[1].__name__)  # RuntimeError

def depth_iter(n):            # explicit loop: no limit at all
    total = 0
    while n:
        n, total = n - 1, total + 1
    return total
print(depth_iter(5000))               # 5000

sys.setrecursionlimit(10_000)
print(depth(5000))                    # 5000

import socket
import sys

opened = []

def hook(event, args):
    if event == "open" and isinstance(args[0], str) and args[0].endswith(".cfg"):
        opened.append((args[0], args[1]))
    elif event == "socket.connect":
        raise PermissionError("network disabled in tests")

sys.addaudithook(hook)      # cannot be removed afterwards

with open("app.cfg", "w") as f:
    f.write("debug=1")
print(opened)               # [('app.cfg', 'w')]

try:
    socket.create_connection(("127.0.0.1", 9), timeout=1)
except PermissionError as e:
    print(e)                # network disabled in tests
